import zen from 'zen';

/** @type {Handler} **/
export const handler = async (input) => {
  // ----------------------------
  // 0. Validación: que exista un concepto a calcular
  // ----------------------------
  const billingItemCode = input?.parametros_de_la_regla?.parameter_billingItem_code ?? null;

  if (!billingItemCode || billingItemCode === "null" || billingItemCode.trim() === "") {
    return {
      ...input,
      result: {
        rule_description: `parameter_billingItem_code for rule Alumbrado publico-Precio por rangos consumo y porcentaje fijo de importe not found`,
        status: 'ERROR',
      }
    };
  }

  // ----------------------------
  // 1. Obtener consumo y monto base
  // ----------------------------
  const parameterBillingItemCodeForAmount = input?.parametros_de_la_regla?.parameter_billingItem_code_for_amount;
  const active_energy_consumption = parseFloat(input.tsl_wo_work_order_attribute.active_energy_consumption ?? 0);

  const billingItemsActiveEnergy = input.tsl_wo_work_order_attribute?.billing_items?.active_energy_billing_items ?? [];
  const active_energy_item = billingItemsActiveEnergy.find(item => item.print_description.toLowerCase() === parameterBillingItemCodeForAmount);
  const active_energy_amount = active_energy_item ? parseFloat(active_energy_item.billing_item_amount) : 0;

  // ----------------------------
  // 2. Extraer rangos de porcentaje
  // ----------------------------
  const percentagePricing = input?.graduated_percentage_pricing?.percentages ?? [];
  const filteredRanges = percentagePricing
    .sort((a, b) => parseFloat(a.interval_high) - parseFloat(b.interval_high))
    .map(r => ({
      limite: parseFloat(r.interval_high),
      precio: parseFloat(input.graduated_percentage_pricing.price_for_unit ?? 0),
      porcentaje: parseFloat(r.percentage ?? 0)
    }));

  if (filteredRanges.length === 0) {
    return {
      ...input,
      result: {
        status: "ERROR",
        status_description: `No percentage ranges found for billing item code ${billingItemCode}`
      }
    };
  }

  // ----------------------------
  // 3. Calcular importe según bloque
  // ----------------------------
  let importe_alumbrado = 0;
  let limite_anterior = 0;
  let i;

  for (i = 0; i < filteredRanges.length; i++) {
    if (active_energy_consumption >= limite_anterior && active_energy_consumption <= filteredRanges[i].limite) {
      break;
    }
    limite_anterior = filteredRanges[i].limite;
  }

  if (limite_anterior === 0) {
    importe_alumbrado = filteredRanges[i].precio; // Precio fijo para el primer bloque
  } else {
    importe_alumbrado = active_energy_amount * (filteredRanges[i].porcentaje / 100);
  }

  // ----------------------------
  // 4. Actualizar billing_item_amount en active_energy_billing_items
  // ----------------------------
  const alumbradoItem = billingItemsActiveEnergy.find(item => item.legacy_billing_item_id === billingItemCode);
  if (alumbradoItem) {
    alumbradoItem.billing_item_amount = importe_alumbrado;
  } else {
    // Si no existe, lo agregamos al final
    billingItemsActiveEnergy.push({
      legacy_billing_item_id: billingItemCode,
      billing_item_amount: importe_alumbrado,
      is_calculate: "true",
      print_order: billingItemsActiveEnergy.length + 1,
      print_description: "Calculo importe alumbrado publico"
    });
  }

  // ----------------------------
  // 5. También actualizar en public_lighting_billing_items si quieres mantener consistencia
  // ----------------------------
  const billingItemsPublicLighting = input.tsl_wo_work_order_attribute?.billing_items?.public_lighting_billing_items ?? [];
  const publicLightingItem = billingItemsPublicLighting.find(item => item.legacy_billing_item_id === billingItemCode);
  if (publicLightingItem) {
    publicLightingItem.billing_item_amount = importe_alumbrado;
  }

  // ----------------------------
  // 6. Resultado
  // ----------------------------
  return {
    ...input,
    result: {
      total_amount: importe_alumbrado,
      status: "OK",
      status_description: "Cálculo de Alumbrado Público-Precio por rangos consumo y porcentaje fijo de importe calculation method completed"
    }
  };
};
